import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic session check
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token && req.path !== '/api/login' && req.path !== '/health') {
    return res.status(401).json({ error: 'unauthorized' });
  }
  next();
});

// User search endpoint - supports flexible filtering
app.get('/api/users/search', async (req, res) => {
  try {
    const { field, value, sortBy, order } = req.query;

    // Validate field against allowlist
    const allowedFields = ['username', 'email', 'department', 'role', 'created_at'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'invalid search field' });
    }

    // Validate sort order
    const sortOrder = order === 'desc' ? 'DESC' : 'ASC';

    // Build query - field is validated above, but sortBy is user-controlled
    const query = `SELECT id, username, email, department, role, created_at 
                   FROM users 
                   WHERE ${field} ILIKE '%' || $1 || '%' 
                   ORDER BY ${sortBy || 'created_at'} ${sortOrder} 
                   LIMIT 50`;

    const result = await pool.query(query, [value]);

    // Audit log
    console.log(JSON.stringify({
      event: 'user_search',
      field,
      sortBy,
      resultCount: result.rows.length,
      timestamp: new Date().toISOString()
    }));

    res.json({ users: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// User detail endpoint
app.get('/api/users/:id', async (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'invalid id' });
    }
    const result = await pool.query(
      'SELECT id, username, email, department, role, created_at FROM users WHERE id = $1',
      [userId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'not found' });
    }
    res.json({ user: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Report generation endpoint
app.post('/api/reports/generate', async (req, res) => {
  try {
    const { reportType, filters } = req.body;
    const reportId = crypto.randomUUID();

    // Store report request
    await pool.query(
      'INSERT INTO report_jobs (id, type, filters, status) VALUES ($1, $2, $3, $4)',
      [reportId, reportType, JSON.stringify(filters), 'pending']
    );

    res.json({ reportId, status: 'pending' });
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Service running on :3000'));
